325	        // Currently axisTick is not involved in estimate kind, and the result likely varies during a
326	        // single pass of ec main process, due to the change of axisExtent. Therefore no cache is used.
327	        const result = axis.calculateCategoryInterval(ctx);
328	        ctx.out.noPxChangeTryDetermine.push(function () {
329	            axisInner(axis).autoInterval = result;
330	            return true;
331	        });
332	        return result;
333	    }
334	    // Both tick and label uses this result, cacah it to avoid recompute.
